// Baked central Krasnodar for the flat-city flood lab — real data from the app's terrain +
// OSM surface loader, area-averaged to the lab grid, centered on 45.0355, 38.9753.
// The plain is gently sloped (only ~9 m of relief across ~1.4 km), but it is NOT
// flat: that subtle topography plus the real building footprints and street grid is exactly
// what routes the flood. Elevation is normalized int16; the masks are 1 byte per cell.
// Generated artifact — do not hand-edit.
export const KRD_W = 144;
export const KRD_H = 92;
export const KRD_CS = 10; // m per cell (~1.44 km × 0.92 km window)

const Z = '';
const BLD = '';
const ROAD = '';

function unb64(s: string): Uint8Array {
  const bin = atob(s);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

/** Real relief normalized to [0,1] (north-up, row-major); LabWorld scales it to the sandbox range. */
export function decodeKrdShape(): Float32Array {
  const q = new Int16Array(unb64(Z).buffer);
  const z = new Float32Array(q.length);
  for (let i = 0; i < q.length; i++) z[i] = q[i] / 32000;
  return z;
}

export function decodeKrdBuilding(): Uint8Array { return unb64(BLD); }
export function decodeKrdRoad(): Uint8Array { return unb64(ROAD); }
